var raw = $input.first().json;
var posts = Array.isArray(raw) ? raw : [raw];
var videoOnly = posts.filter(function(p) { return p.videoUrl && (p.videoViewCount || p.likesCount); });
var normalized = videoOnly.map(function(p) {
  return {
    shortCode: p.shortCode || p.id || String(Date.now() + Math.random()).replace('.',''),
    url: p.url || ('https://www.instagram.com/p/' + (p.shortCode || '')),
    username: p.ownerUsername || p.username || '',
    hashtag: p.hashtag || '',
    caption: (p.caption || p.text || '').slice(0, 500),
    displayUrl: p.displayUrl || p.thumbnailUrl || p.previewUrl || '',
    videoUrl: p.videoUrl || '',
    views: p.videoViewCount || 0,
    likes: p.likesCount || 0,
    followers: p.followersCount || 0,
    normalized_reach: (p.followersCount > 100)
      ? Math.round((p.videoViewCount / p.followersCount) * 100)
      : (p.videoViewCount || 0)
  };
});
normalized.sort(function(a, b) { return b.normalized_reach - a.normalized_reach; });
var count = Math.max(1, Math.ceil(normalized.length * 0.2));
var top = normalized.slice(0, count);
console.log('Total: ' + normalized.length + ', Top 20%: ' + top.length);
return top.map(function(p) { return {json: p}; });

